// ─── Translation helper ───
// Falls back to English if key not found in active language.
// Falls back to the raw key string if not in English either.
function t(key, vars) {
  const lang = (typeof S !== 'undefined' && S && S.settings && S.settings.lang) || 'en';
  let str = (TRANSLATIONS[lang] && TRANSLATIONS[lang][key])
         || (TRANSLATIONS.en && TRANSLATIONS.en[key])
         || key;
  if (vars) {
    Object.keys(vars).forEach(function(k){
      str = str.split('{' + k + '}').join(vars[k]);
    });
  }
  return str;
}

// ─── Available languages for the language picker ───
// `name` is the language's NATIVE name (shown as the card heading).
// `english` is the language's name in English — always English regardless of
// the active UI language. Used as the secondary subtitle on the language cards
// and the "Currently …" badge, so the user can always identify the language
// even when the UI is in a script they can't read.
const FOCAL_LANGS = [
  { code: 'en', name: 'English',    english: 'English'    },
  { code: 'nl', name: 'Nederlands', english: 'Dutch'      },
  { code: 'de', name: 'Deutsch',    english: 'German'     },
  { code: 'it', name: 'Italiano',   english: 'Italian'    },
  { code: 'pt', name: 'Português',  english: 'Portuguese' },
  { code: 'es', name: 'Español',    english: 'Spanish'    },
  { code: 'hi', name: 'हिन्दी',       english: 'Hindi'      },
];
